def solve(overrides):
    rows = []
    for key, value in overrides.collect():
        spark.conf.set(key, value)
        rows.append((key, True, spark.conf.get(key)))
    # spark.createDataFrame builds a DataFrame from a list of Python tuples, with these columns and types.
    return spark.createDataFrame(rows, "key STRING, applied BOOLEAN, value STRING")
